    "XGBoost": {"increment": 1918.3121807837142},
    "LightGBM": {"increment": 2142.5456286266544}
}

# 計算平均增量
total_increment = sum(m["increment"] for m in metrics.values())
avg_increment = total_increment / len(metrics)

# 計算電費 (每度 4 元)
electricity_cost_per_kwh = 4.0
electricity_cost = avg_increment * electricity_cost_per_kwh

# 計算各模型的電費
model_costs = {
    model: m["increment"] * electricity_cost_per_kwh 
    for model, m in metrics.items()
}

# 整理報告
report = {
    "預測期間": "2026-06-01 至 2026-06-30 (30 天)",
    "電力消耗增量 (kWh)": {
        "BaselineLastWeek": 804.91,
        "Prophet": 129.10,
        "XGBoost": 1918.31,
        "LightGBM": 2142.55
    },
    "平均電力消耗增量 (kWh)": round(avg_increment, 2),
    "電價 (元/kWh)": electricity_cost_per_kwh,
    "預估電費 (元)": round(electricity_cost, 2),
    "各模型預估電費 (元)": {k: round(v, 2) for k, v in model_costs.items()}
}

print(json.dumps(report, ensure_ascii=False, indent=2))","timeout":30}

